#!/bin/bash
cd /testbed || { echo RH2_PREFLIGHT_INTERPRETER=fail:no_testbed; exit 0; }
if /testbed/.venv/bin/python -B -I -S -c pass >/dev/null 2>&1; then echo RH2_PREFLIGHT_INTERPRETER=ok; else echo RH2_PREFLIGHT_INTERPRETER=fail:not_executable_as_agent; fi
if [ -e /r2e_tests ]; then echo RH2_PREFLIGHT_HIDDEN_TESTS=fail:root_copy_present; elif [ -e /testbed/r2e_tests ]; then echo RH2_PREFLIGHT_HIDDEN_TESTS=fail:workdir_copy_present; elif ls /rh2_private/r2e_tests >/dev/null 2>&1 || [ -r /rh2_private/r2e_tests ]; then echo RH2_PREFLIGHT_HIDDEN_TESTS=fail:private_location_readable; else echo RH2_PREFLIGHT_HIDDEN_TESTS=ok; fi
RH2_HEAD=$(git rev-parse HEAD 2>/dev/null) || RH2_HEAD=""
if [ -z "$RH2_HEAD" ]; then echo RH2_PREFLIGHT_GIT_HISTORY=fail:no_head;
elif ! RH2_CHILDREN=$(git rev-list --children --all 2>/dev/null); then echo RH2_PREFLIGHT_GIT_HISTORY=fail:rev_list_failed;
elif [ "$(printf '%s\n' "$RH2_CHILDREN" | grep "^$RH2_HEAD" | wc -w | tr -d " ")" != "1" ]; then echo RH2_PREFLIGHT_GIT_HISTORY=fail:head_has_children_or_is_unlisted;
else echo RH2_PREFLIGHT_GIT_HISTORY=ok; fi

